/**
 * THE VIEW THROUGH THE WINDOW, PAINTED.
 *
 * The same hill, oak, wall and farmhouse in each of the four seasons, cut from
 * one supplied 2x2 sheet. Painted calm and dry on purpose: the weather is laid
 * over the view by `IsoWindow` (rain, snow, the low sun), because the weather
 * changes by the day and the season by the month, and a painting cannot do both.
 *
 * Portrait, sized at twice the painted opening (134x170) so it covers the hole
 * without softening. Data URIs because the published page's CSP blocks images.
 */
export type WindowSeason = 'winter' | 'spring' | 'summer' | 'autumn';

export const WINDOW_VIEW: Record<WindowSeason, { w: number; h: number; src: string }> = {
  spring: { w: 272, h: 340, src: 'data:image/webp;base64,' },
  summer: { w: 272, h: 340, src: 'data:image/webp;base64,' },
  autumn: { w: 272, h: 340, src: 'data:image/webp;base64,' },
  winter: { w: 272, h: 340, src: 'data:image/webp;base64,' },
};
